#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos{1, 4, 7};
    if (datos.empty()) {
        std::cout << "No data";
        return 0;
    }
    int suma{0};
    int minimo{datos[0]};
    int maximo{datos[0]};
    for (int dato : datos) {
        suma += dato;
        if (dato < minimo) { minimo = dato; }
        if (dato > maximo) { maximo = dato; }
    }
    int cantidad{static_cast<int>(datos.size())};
    double media{static_cast<double>(suma) / cantidad};
    bool dentro{media >= minimo && media <= maximo};
    std::cout << "Sum=" << suma << " Mean=" << media
              << " Minimum=" << minimo << " Maximum=" << maximo
              << " InRange=" << dentro;
    return 0;
}
